mapper.select:
SELECT * FROM ( SELECT
TB.* FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.BROD_CODE DESC) AS RNUM, A.BROD_CODE AS brodCode, A.BROD_NAME AS brodName, A.BROD_TOTALTIME AS brodTotalTime, A.BROD_USEYN AS brodUseYn, A.BROD_INTERVAL AS brodInterval, B.CODE_NM AS codeNm, C.BASIC_GROUP_NM AS orignlFileNm, FN_DETAILCODENM(A.SEC_GUBUN) AS secGubun, A.CENTER_ID AS centerId, A.CENTER_RELCNT AS centerRelCnt, D.CENTER_NM AS centerNm FROM TB_BRODSCHEDULE A JOIN LETTCCMMNDETAILCODE B ON A.BROD_INTERVAL = B.CODE LEFT OUTER JOIN TB_CENTERINFO D ON A.CENTER_ID = D.CENTER_ID LEFT OUTER JOIN TB_BRODBASICGROUP C ON A.BASIC_FILE_ID = C.BASIC_CODE WHERE 1=1
AND A.BROD_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND D.CENTER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND C.BASIC_GROUP_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.SEC_GUBUN = #{secGubun}
AND A.CENTER_ID IS NULL
AND A.CENTER_ID IS NOT NULL
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT BROD_CODE
FROM TB_BRODSCHEDULE
WHERE CENTER_ID = #{centerId}

SELECT BASIC_BROD_CODE
FROM TB_BRODSCHEDULE
WHERE BROD_CODE = #{brodCode}

SELECT BASIC_BROD_CODE
FROM TB_BRODSCHEDULE
WHERE CENTER_ID = #{centerId}

SELECT COALESCE(BASIC_BROD_CODE, '')
FROM TB_BRODSCHEDULE
WHERE BROD_CODE = #{brodCode}

mapper.update:
UPDATE TB_BRODSCHEDULE SET
    BROD_CHANGEINFO = #{brodChangeInfo}
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
    CENTER_RELCNT = CENTER_RELCNT + 1
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
    CENTER_RELCNT = CENTER_RELCNT - 1
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
    BROD_TOTALTIME = #{brodTotalTime}
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
                           CENTER_ID = #{centerId,jdbcType=VARCHAR},
                           BASIC_BROD_CODE = #{basicBrodCode,jdbcType=VARCHAR}
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
                           CENTER_ID = #{centerId,jdbcType=VARCHAR},
                           BASIC_BROD_CODE = #{basicBrodCode,jdbcType=VARCHAR},
                           BROD_NAME = #{brodName}
WHERE BROD_CODE = #{brodCode}

UPDATE TB_BRODSCHEDULE SET
    BASIC_FILE_ID = #{basicBrodCode,jdbcType=VARCHAR}
WHERE BROD_CODE = #{brodCode}
  AND CENTER_ID = #{centerId}
